GALV_TimedMessagePopups
JavaScript:
Galv.Mpup.Game_Interpreter_command101 = Game_Interpreter.prototype.command101;
Game_Interpreter.prototype.command101 = function() {
    var cap = this._list[this._index + 1].parameters[0].match(/<c:(.*)>/i);

    var pos = 2; //this._params[3];
    var data = this._params.clone();

    if (!cap) {
        return Galv.Mpup.Game_Interpreter_command101.call(this);
    } else {
        this.createCaption(cap,pos,data);
        this._index++; // skip the original command101 execution
    };
};
GALV_MessageStylesMZ
JavaScript:
Galv.Mstyle.Game_Interpreter_command101 = Game_Interpreter.prototype.command101;
Game_Interpreter.prototype.command101 = function(params) {
    const ispop = this._list[this._index + 1].parameters[0].match(/\\pop/i);
    if (ispop) {
        // Is a pop message
        Galv.Mstyle.thisEvent = this._eventId;
        Galv.Mstyle.target = Galv.Mstyle.setTarget(Galv.Mstyle.checkTarget(this._list[this._index + 1].parameters[0]));

        if (Galv.Mstyle.target == false) {
            while (this.nextEventCode() === 401) {  // Text data
                this._index++;
            };
            return false;
        };
    } else {
        // Not a pop message
        Galv.Mstyle.thisEvent = null;
        Galv.Mstyle.target = null;
    };
    return Galv.Mstyle.Game_Interpreter_command101.call(this,params);
};
